package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net/http"

	greetv1 "example/gen/greet/v1"        // generated by protoc-gen-go
	"example/gen/greet/v1/greetv1connect" // generated by protoc-gen-connect-go
	"example/middleware"

	"connectrpc.com/connect"
	"connectrpc.com/otelconnect"
	"connectrpc.com/validate"
)

type GreetServer struct{}

func (s *GreetServer) Greet(
	_ context.Context,
	req *greetv1.GreetRequest,
) (*greetv1.GreetResponse, error) {
	res := &greetv1.GreetResponse{
		Greeting: fmt.Sprintf("Hello, %s!", req.Name),
	}
	log.Println("Greet request:", req.Name, "response:", res.Greeting)
	return res, nil
}

func (s *GreetServer) Header(
	_ context.Context,
	req *greetv1.HeaderRequest,
) (*greetv1.HeaderResponse, error) {
	result := req.RequestId + 1
	log.Println("Header request_id:", req.RequestId, "response_id:", result)
	return &greetv1.HeaderResponse{
		RequestId: result,
	}, nil
}

func (s *GreetServer) Profile(
	ctx context.Context,
	_ *greetv1.ProfileRequest,
) (*greetv1.ProfileResponse, error) {
	callInfo, ok := connect.CallInfoForHandlerContext(ctx)
	if !ok {
		return nil, errors.New("can't access headers: no CallInfo for handler context")
	}
	fmt.Println(callInfo.RequestHeader().Get("JWT-TOKEN"))
	log.Println("Profile request received")
	return &greetv1.ProfileResponse{
		Name:        "Jane Doe",
		PhoneNumber: "+1-555-0100",
		Email:       "jane@example.com",
	}, nil
}

func (s *GreetServer) CreateAccount(
	ctx context.Context,
	req *greetv1.CreateAccountRequest,
) (*greetv1.CreateAccountResponse, error) {
	log.Println("CreateAccount request received")
	return &greetv1.CreateAccountResponse{
		Name:        req.Name,
		PhoneNumber: req.PhoneNumber,
		Email:       req.Email,
	}, nil
}

func (s *GreetServer) Login(
	ctx context.Context,
	req *greetv1.LoginRequest,
) (*greetv1.LoginResponse, error) {
	log.Println("Login request received")
	callInfo, ok := connect.CallInfoForHandlerContext(ctx)
	if !ok {
		return nil, errors.New("can't access headers: no CallInfo for handler context")
	}
	fmt.Println(callInfo.RequestHeader().Get("JWT-TOKEN"))
	return &greetv1.LoginResponse{
		Token: "valid-token",
	}, nil
}

func main() {
	otelInterceptor, err := otelconnect.NewInterceptor()
	if err != nil {
		log.Fatal(err)
	}
	greeter := &GreetServer{}
	mux := http.NewServeMux()

	path, handler := greetv1connect.NewGreetServiceHandler(
		greeter,
		// Validation via Protovalidate is almost always recommended
		connect.WithInterceptors(validate.NewInterceptor()),
		connect.WithInterceptors(otelInterceptor),
	)

	// ignore the following line if you want to use the default path

	mux.Handle(path, handler)
	p := new(http.Protocols)
	p.SetHTTP1(true)
	// Use h2c so we can serve HTTP/2 without TLS.
	p.SetUnencryptedHTTP2(true)
	s := http.Server{
		Addr:      "localhost:8080",
		Handler:   middleware.JwtMiddleware(mux),
		Protocols: p,
	}
	fmt.Println("Server started")
	s.ListenAndServe()

}
